function chosen(asset,selection,prefs){return isCore(asset)||selection==='all'||(selection==='reader-all'&&asset.group==='reader')||(selection==='pinyin-all'&&asset.group==='pinyin')||(selection==='saved'?(prefs.all||asset.units?.some(u=>prefs.units.includes(u))):asset.units?.includes(selection));}
